(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.009+t*0.15)*8;
  let wy = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12 + Math.cos((x-y)*0.011-t*0.18)*8;
  const sx = x + wx, sy = y + wy;
  let wx2 = Math.sin(sx*0.025-t*0.4)*10 + Math.cos(sy*0.02+t*0.35)*7;
  let wy2 = Math.cos(sy*0.025+t*0.45)*10 + Math.sin(sx*0.022-t*0.38)*7;
  const sx2 = sx + wx2, sy2 = sy + wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.9],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.5+2)*40, 0.13, 1.4, 0.6],
    [400+Math.cos(t*0.45+1)*60, 220+Math.sin(t*0.65+4)*50, 0.075, 2.1, 1.3],
    [200+Math.sin(t*0.55+6)*110, 50+Math.cos(t*0.75+1)*60, 0.1, 1.8, 0.85]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx2-sX)**2 + (sy2-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * wt;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.5) * wt;
    wS += Math.sin(d*f*1.4 - t*sp*0.8 + 2.8) * wt * 0.5;
  }
  const tw = 7.65;
  const act = aS/tw, inh = iS/tw, wav = wS/tw;
  const bg = (Math.sin(sx2*0.035+sy2*0.022+t*0.8) + Math.sin(sx2*0.028-sy2*0.038+t*1.1) + Math.sin(sx2*0.045+sy2*0.045-t*0.6))/3;
  const dist = Math.sqrt((sx2-cx)**2 + (sy2-cy)**2), ang = Math.atan2(sy2-cx, sx2-cy);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.5) + Math.sin(dist*0.035+ang*5-t*1.2) + Math.sin(dist*0.06-ang*2-t*2.0))*0.3;
  const moire = Math.sin(sx2*0.08)*Math.sin(sy2*0.08)*0.4 + Math.sin((sx2+sy2)*0.06-t*1.5)*Math.sin((sx2-sy2)*0.06+t*1.2)*0.3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral*0.35 + wav*0.2 + moire*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx2*0.13)*Math.sin(sy2*0.13) + Math.sin((sx2+sy2)*0.09+t)*0.5 + Math.sin(sx2*0.17-t*0.8)*Math.cos(sy2*0.14+t*0.6)*0.3)*1.4)*0.25;
  const pulse = Math.sin(dist*0.03-t*2.0)*0.5+0.5;
  const edgeGlow = Math.exp(-Math.abs(reaction)*4)*0.15 * (1+Math.sin(t*3)*0.3);
  const blend = reaction*0.6 + cell*0.2 + moire*0.1 + edgeGlow + pulse*0.05;
  const v = Math.tanh(blend*1.3)*0.5+0.5;
  const pal = [
    [6,12,42],[10,35,78],[12,65,105],[18,110,125],[35,155,130],
    [90,175,115],[165,190,85],[210,175,60],[225,140,50],[210,95,55],
    [185,60,60],[145,35,55],[95,22,48],[50,15,42],[20,10,38],[6,12,42]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15 + edgeGlow*2;
  const edge = Math.abs(reaction)>0.65 ? 1.1 + Math.sin(t*2)*0.05 : 1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge)|0
  ];
}
